/*
 * Compatibility layer to provide the same results youtube-comment-api
 * used to provide.
 */

var fetchVideoComments = require('youtube-comments-task')
var fetchInfo = require('./fetch-video-info')

module.exports = function (videoId, pageToken) {
  return Promise.all([
    fetchInfo(videoId),
    fetchComments(videoId, pageToken)
  ])
    .then(function (results) {
      var info = results[0]
      var page = results[1]

      if (!page) {
        throw new Error('No comment page received.')
      }

      var comments = page.comments || []
      var nextPageToken = page.nextPageToken

      var compatComments = comments
        .map(compatComment)
        .map(function (c) {
          var replies = c.hasReplies ? c.replies.map(compatComment) : null
          return replies ? Object.assign({}, c, { replies: replies }) : c
        })

      // build the response
      return {
        comments: compatComments,
        nextPageToken: nextPageToken,
        pageToken: pageToken,
        videoCommentCount: info.commentCount,
        videoTitle: info.title,
        videoThumbnail: info.thumbnailUrl
      }
    })
}

function fetchComments (videoId, pageToken) {
  return new Promise(function (res, rej) {
    fetchVideoComments(videoId, pageToken)
      .fork(rej, res)
  })
}

function compatComment (c) {
  const compat = {
    id: c.id,
    user: c.author,
    date: c.time,
    commentText: c.text,
    timestamp: c.timestamp,
    likes: c.likes
  }

  // return as-is if it's a reply
  if (c.hasReplies == null) {
    return compat
  }

  compat.hasReplies = c.hasReplies
  if (c.hasReplies) {
    compat.numberOfReplies = c.numReplies
    compat.replies = c.replies
  }

  return compat
}

Q:

Get Google Maps v3 corner coordinates from iFrame to parent page

I have a Google Map with marker data pulled from my database on my website inside an iFrame. I know that with Maps v3 it is possible to get the new corner GPS coordinates when the map is moved in JavaScript.
Is it possible to pass this map information from the map page inside the iFrame to the parent page so I can change the content on the parent page to match what the map is showing with JavaScript? Both pages are on my same server. I imagine that worst case scenario I can just have the JavaScript write the map corner info to a session variable and read that on the parent, but is there a simpler way?

A:

You don't show any HTML or code, so I can't be specific, but it's pretty straightforward to get information from an iFrame.
Suppose frameId is the ID of your iFrame and mapId is the ID of the map in that iFrame. Then:
var iframe = document.getElementById('iframeId');
var iframeDoc = iframe.contentDocument || iframe.contentWindow.document;

You now have the iFrame document and can do the usual:
var map = iframeDoc.getElementById('mapId');
var bounds = map.getBounds();

